class _ManualAttendanceScreenState extends State<ManualAttendanceScreen>{List<dynamic> employees=[];int? employeeId;String status='present';bool saving=false;final reason=TextEditingController();TimeOfDay inTime=const TimeOfDay(hour:9,minute:0),outTime=const TimeOfDay(hour:17,minute:30);@override void initState(){super.initState();_load();}@override void dispose(){reason.dispose();super.dispose();}Future<void> _load()async{try{final d=await widget.session.employees();if(mounted)setState(()=>employees=d['employees'] as List<dynamic>? ?? []);}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}}Future<void> _save()async{if(employeeId==null)return;setState(()=>saving=true);try{final now=DateTime.now(); String stamp(TimeOfDay time)=>DateTime(now.year,now.month,now.day,time.hour,time.minute).toIso8601String(); await widget.session.manualAttendance(employeeId!,status,note:reason.text.trim(),punchInAt:status=='absent'?null:stamp(inTime),punchOutAt:status=='absent'?null:stamp(outTime));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Manual attendance saved')));}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext context)=>Scaffold(backgroundColor:const Color(0xFFF5F8FC),appBar:AppBar(backgroundColor:const Color(0xFFF5F8FC),title:const Text('Manual attendance',style:TextStyle(color:Color(0xFF0F2440),fontWeight:FontWeight.w800))),body:ListView(padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[HRMateTheme.blue,HRMateTheme.green]),borderRadius:BorderRadius.circular(22)),child:const Text('Supervisor attendance entry',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w800))),const SizedBox(height:20),DropdownButtonFormField<int>(value:employeeId,isExpanded:true,decoration:const InputDecoration(labelText:'Select employee',filled:true,fillColor:Colors.white),items:employees.map((e)=>DropdownMenuItem(value:e['id'] as int,child:Text('${e['name']} · ${e['employee_code']??''}'))).toList(),onChanged:(v)=>setState(()=>employeeId=v)),const SizedBox(height:18),const Text('Status',style:TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:8),SegmentedButton<String>(segments:const [ButtonSegment(value:'present',label:Text('Present')),ButtonSegment(value:'half_day',label:Text('Half day')),ButtonSegment(value:'absent',label:Text('Absent'))],selected:{status},onSelectionChanged:(s)=>setState(()=>status=s.first)),const SizedBox(height:18),Row(children:[Expanded(child:OutlinedButton(onPressed:()async{final t=await showTimePicker(context:context,initialTime:inTime);if(t!=null)setState(()=>inTime=t);},child:Text('In ${inTime.format(context)}'))),const SizedBox(width:10),Expanded(child:OutlinedButton(onPressed:()async{final t=await showTimePicker(context:context,initialTime:outTime);if(t!=null)setState(()=>outTime=t);},child:Text('Out ${outTime.format(context)}')))]),const SizedBox(height:14),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason / correction note',filled:true,fillColor:Colors.white,border:OutlineInputBorder())),const SizedBox(height:20),FilledButton(onPressed:saving?null:_save,style:FilledButton.styleFrom(backgroundColor:HRMateTheme.blue,padding:const EdgeInsets.symmetric(vertical:17)),child:Text(saving?'Saving…':'Save attendance')),const SizedBox(height:14),const Text('This entry will be recorded in audit history',textAlign:TextAlign.center,style:TextStyle(color:Color(0xFF71859A),fontSize:12))]));}
